import java.io.*;
import java.util.*;

public class HeightAllTheSame {
    public static void main(String[] args) throws Exception {
        DataInputStream dis = new DataInputStream(System.in);
        long N = readLong(dis);
        long M = readLong(dis);
        long L = readLong(dis);
        long R = readLong(dis);

        long total = R - L + 1;
        long E = total / 2 + (total % 2 == 0 && L % 2 == 0 ? 1 : 0);
        long O = total - E;

        long answer;
        if ((N * M) % 2 == 1) {
            answer = fastExponentiation(E + O, N * M);
        } else {
            answer = (fastExponentiation(E + O, N * M) + fastExponentiation(E - O, N * M)) % mod;
            answer = (answer * modInverse(2)) % mod;
        }
        System.out.println(answer);
    }

    static long mod = 998244353;

    static long readLong(DataInputStream dis) throws IOException {
        long res = 0;
        boolean neg = false;
        int c = dis.read();
        while (c != -1 && (c < '0' || c > '9')) {
            if (c == '-') neg = true;
            c = dis.read();
        }
        while (c >= '0' && c <= '9') {
            res = res * 10 + c - '0';
            c = dis.read();
        }
        return neg ? -res : res;
    }

    static long modInverse(long x) {
        return fastExponentiation(x, mod - 2);
    }

    static long fastExponentiation(long base, long exp) {
        long result = 1;
        long b = base % mod;
        long e = exp;
        while (e > 0) {
            if ((e & 1) == 1) {
                result = (result * b) % mod;
            }
            b = (b * b) % mod;
            e >>= 1;
        }
        return result;
    }
}
